mapper.select:
SELECT id, user_id, shipping_address_province, shipping_address_city, shipping_address_district, shipping_address_detail, shipping_address_zip_code, total_amount, status, tenant_id, version, deleted, created_by, created_at, updated_by, updated_at FROM t_order WHERE deleted = FALSE
AND user_id = #{userId}
AND status = #{status}
ORDER BY created_at DESC
